#include <torch/extension.h>
#include <cuda_runtime.h>

// optimized kernel using shared memory
__global__ void square_matrix_multiply_shared_kernel(const float* A, const float* B, float* C, int N) {
    // block size, assuming square blocks
    const int BLOCK_SIZE = 16;

    // shared memory for tiles of A and B
    __shared__ float sA[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float sB[BLOCK_SIZE][BLOCK_SIZE];

    int globalRow = blockIdx.y * BLOCK_SIZE + threadIdx.y;
    int globalCol = blockIdx.x * BLOCK_SIZE + threadIdx.x;

    float sum = 0.0f;

    // loop over tiles
    for (int tile = 0; tile < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; ++tile) {
        // load tile of A into shared memory
        int tiledRow = blockIdx.y * BLOCK_SIZE + threadIdx.y;
        int tiledColA = tile * BLOCK_SIZE + threadIdx.x;
        if (tiledRow < N && tiledColA < N) {
            sA[threadIdx.y][threadIdx.x] = A[tiledRow * N + tiledColA];
        } else {
            sA[threadIdx.y][threadIdx.x] = 0.0f; // pad with zeros
        }

        // load tile of B into shared memory
        int tiledRowB = tile * BLOCK_SIZE + threadIdx.y;
        int tiledCol = blockIdx.x * BLOCK_SIZE + threadIdx.x;
        if (tiledRowB < N && tiledCol < N) {
            sB[threadIdx.y][threadIdx.x] = B[tiledRowB * N + tiledCol];
        } else {
            sB[threadIdx.y][threadIdx.x] = 0.0f; // pad with zeros
        }

        __syncthreads(); // synchronize to ensure tiles are loaded

        // perform matrix multiplication on tiles
        for (int k = 0; k < BLOCK_SIZE; ++k) {
            sum += sA[threadIdx.y][k] * sB[k][threadIdx.x];
        }

        __syncthreads(); // synchronize to ensure all calculations are done for this tile
